import {beginBottomDialogue} from './bottom-dialogue.js';
import {ULTIMATE_CINEMATIC_STEPS} from '../engine/ultimate-rules.js';
import {TATSUMAKI_META} from './tatsumaki-meta.js';
import {tatsumakiPose} from '../characters/tatsumaki.js';
import {personalCaster} from '../engine/personal-ultimate.js';
export function tatsuSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const im=images[key],m=TATSUMAKI_META[key];if(!im?.complete||!im.naturalWidth||!m)return;const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,Math.max(0,Math.min(m.columns-1,col))*w,Math.max(0,Math.min(m.rows-1,row))*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawTatsuActor(ctx,images,d,f,hurt=false,override=null){const c=personalCaster(d,f),a=d.personalUltimate?.attack;let pose=override||tatsumakiPose(f,hurt);if(c?.kind==='cataclysm')pose={row:11,frame:Math.min(5,Math.floor((d.personalUltimate.cinematic?.elapsed??ULTIMATE_CINEMATIC_STEPS+d.tick-c.born)/10))};else if(a?.kind==='cataclysm'&&a.ownerUid===f.uid&&d.tick-a.launch<45)pose={row:12,frame:Math.min(5,Math.floor((d.tick-a.launch)/7))};if(f.state==='defeat')pose={row:6,frame:Math.min(5,Math.floor((d.tick-(f.deathTick??d.tick))/6))};const y=f.introAge!=null&&f.introAge<.9?f.y+25-18*f.introAge/.9:f.y;tatsuSprite(ctx,images,f.introAge!=null?'tatsumaki_intro':'tatsumaki',pose.row,pose.frame,f.x,y,((f.introAge!=null&&pose.row>0)||pose.row>=11)?.72:.8,0,f.face);}
export function drawTatsuBack(ctx,images,d){for(const f of d.fighters)if(f.id==='tatsumaki'&&f.hp>0&&f.introAge!=null){const age=f.introAge;ctx.save();ctx.globalAlpha=Math.min(1,Math.max(0,(age-.3)*5),(2.5-age)*5);if(age>.3)tatsuSprite(ctx,images,'tatsumaki_intro_vfx',0,Math.min(5,Math.floor((age-.3)/2.2*6)),f.x,f.y,.75);if(age>.75&&age<2.1)tatsuSprite(ctx,images,'tatsumaki_intro_vfx',1,Math.min(5,Math.floor((age-.75)/1.35*6)),f.x,f.y-60,.65);ctx.restore();}}
function ring(ctx,x,y,r,color){ctx.save();ctx.strokeStyle=color;ctx.lineWidth=2;ctx.setLineDash([12,8]);ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.stroke();ctx.restore();}
export function drawTatsuWorld(ctx,images,d,reduced=false){for(const f of d.fighters)if(f.id==='tatsumaki'&&f.hp>0){for(const z of f.psychicZones){if(z.kind==='crush'){const p=Math.max(0,Math.min(1,(d.tick-z.born)/60));if(!z.hit)ring(ctx,z.x,z.y,105,'#7dffb0');tatsuSprite(ctx,images,'tatsumaki_vfx',1,z.hit?4+Math.min(1,Math.floor((d.tick-z.detonate)/15)):Math.min(3,Math.floor(p*4)),z.x,z.y-15,.78);}else{ctx.save();ctx.globalAlpha=Math.min(1,(z.expires-d.tick)/15);tatsuSprite(ctx,images,'tatsumaki_vfx',3,1+Math.floor((d.tick-z.born)/8)%4,z.x,z.y-45,.85);ctx.restore();}}if(f.introAge!=null&&f.introAge>1.3&&f.introAge<2){ctx.save();ctx.globalAlpha=.55;tatsuSprite(ctx,images,'tatsumaki_intro_vfx',2,Math.min(5,Math.floor((f.introAge-1.3)/.7*6)),f.x,f.y-60,.7);ctx.restore();}}
 const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if(c?.kind==='cataclysm')tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',0,Math.min(5,Math.floor(c.elapsed/10)),c.x,Math.max(95,c.y-105),.85);
 if(a?.kind!=='cataclysm')return;if(a.phase==='warning'){ring(ctx,a.targetX,a.targetY,165,'#99ffc6');tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',2,Math.min(2,Math.floor((d.tick-a.born)/12)),a.targetX,a.targetY,.95);tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',0,3+Math.min(2,Math.floor((d.tick-a.born)/12)),a.x,Math.max(95,a.y-105),.85);}else if(!a.hit){const p=Math.min(1,(d.tick-a.launch)/30);ring(ctx,a.targetX,a.targetY,165,'#a4ffcb');tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',1,Math.min(5,Math.floor(p*6)),a.targetX-(reduced?0:90*(1-p)),a.targetY-35-(reduced?100:240)*(1-p),1.25);}else{ctx.save();ctx.globalAlpha=Math.max(0,1-(d.tick-a.impactTick)/48);tatsuSprite(ctx,images,'tatsumaki_ultimate_vfx',3,Math.min(5,Math.floor((d.tick-a.impactTick)/8)),a.targetX,a.targetY-25,1.55);ctx.restore();}}
export function drawTatsuShot(ctx,images,s,x,y,clock){if(s.kind==='psychicbolt'){ctx.save();ctx.fillStyle='#c2ffe3';ctx.shadowColor='#4aff9e';ctx.shadowBlur=14;ctx.beginPath();ctx.arc(x,y,7,0,Math.PI*2);ctx.fill();ctx.restore();return;}tatsuSprite(ctx,images,'tatsumaki_vfx',0,2+Math.floor(clock*12)%2,x,y,.65,Math.atan2(s.vy,s.vx));}
export function drawTatsuChat(ctx,images,c,line='Know your place.',reduced=false){const p=c.elapsed/ULTIMATE_CINEMATIC_STEPS;beginBottomDialogue(ctx,'tatsumaki');ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));const slide=reduced?0:Math.max(0,1-p*9)*65;tatsuSprite(ctx,images,'tatsumaki_dialogue',0,p>.45?1:0,480+slide,310,.8);tatsuSprite(ctx,images,'tatsumaki_dialogue',2,p>.5?1:0,225+slide,315,.23);ctx.textAlign='center';ctx.fillStyle='#d8ffea';ctx.font='bold 17px Georgia';ctx.fillText('TATSUMAKI',408+slide,266,160);ctx.font='bold 31px Georgia';ctx.fillText(line,575+slide,328,480);ctx.restore();}
export function drawTatsuCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic,a=d.personalUltimate?.attack;if((c||a)?.kind!=='cataclysm')return;if(c)drawTatsuChat(ctx,images,c,undefined,reduced);else if(a.phase==='travel'&&d.tick-a.launch<48){ctx.save();ctx.globalAlpha=Math.min(1,(48-d.tick+a.launch)/12);tatsuSprite(ctx,images,'tatsumaki_dialogue',3,0,480,92,.6);ctx.restore();}}
